// Simulation adapter: replace this object with normalized sensor or SUMO snapshots.
const initial={floors:[77,74,82,80,76,85,72],queue:42,delay:12};
const phases=[{minutes:'0–3 min',floors:[1,4,7],label:'1, 4 & 7'},{minutes:'3–6 min',floors:[2,5],label:'2 & 5'},{minutes:'6–9 min',floors:[3,6],label:'3 & 6'}];
let state; const $=id=>document.getElementById(id);
function reset(){state={floors:[...initial.floors],queue:initial.queue,delay:initial.delay,phase:0,enabled:true,updates:0};render()}
function render(){const p=phases[state.phase], avg=Math.round(state.floors.reduce((a,b)=>a+b,0)/7);$('occupancy').textContent=avg;$('overall-bar').style.width=avg+'%';$('queue').textContent=state.queue;$('delay').textContent=state.delay;$('mode').setAttribute('aria-pressed',state.enabled);$('mode-label').textContent=state.enabled?'Active':'Inactive';$('advance').disabled=!state.enabled;$('updated').textContent=state.updates?`${state.updates} simulated update${state.updates===1?'':'s'}`:'Initial state';
$('floors').innerHTML=state.floors.map((value,i)=>{const floor=i+1,active=state.enabled&&p.floors.includes(floor),signal=state.enabled?(active?'exit':'wait'):'idle',word=state.enabled?(active?'EXIT':'WAIT'):'OFF';return `<div class="floor-row"><span>Floor ${floor}</span><div class="occupancy-cell"><div class="track"><div class="fill" style="width:${value}%"></div></div><span>${value}%</span></div><span class="signal ${signal}"><b aria-hidden="true">${active?'→':state.enabled?'Ⅱ':'–'}</b>${word}</span></div>`}).reverse().join('');
$('phase-label').innerHTML=state.enabled?`<span class="dot green"></span> PHASE ${state.phase+1} ACTIVE`:'<span class="dot amber"></span> EVENT EGRESS INACTIVE';$('phase-title').textContent=state.enabled?`Floors ${p.label} exit`:'Event egress paused';$('phase-description').textContent=state.enabled?'Directing selected floors to the exit':'Enable event egress mode to display phase signals';$('phase-number').innerHTML=`0${state.phase+1} <small>/ 03</small>`;$('steps').innerHTML=phases.map((step,i)=>`<div class="step ${state.enabled&&i===state.phase?'active':''}"><strong>${step.minutes}</strong><span>Floors ${step.label}</span></div>`).join('');$('sign-go').textContent=state.enabled?`FLOORS ${p.label}: EXIT`:'EVENT EGRESS INACTIVE';$('sign-wait').innerHTML=state.enabled?'ALL OTHER FLOORS: <em>WAIT</em>':'NO ACTIVE EXIT INSTRUCTIONS';}
$('advance').addEventListener('click',()=>{if(!state.enabled)return;const exiting=phases[state.phase].floors;exiting.forEach(f=>state.floors[f-1]=Math.max(0,state.floors[f-1]-3));state.queue=Math.max(0,state.queue-4);state.delay=Math.max(0,state.delay-1);state.phase=(state.phase+1)%3;state.updates++;render()});$('reset').addEventListener('click',reset);$('mode').addEventListener('click',()=>{state.enabled=!state.enabled;render()});reset();
